async function loadEngines(){const query=$('#engineSearch').value,offset=state.engOffset,generation=++enginesGeneration;const r=await api(`profiles?q=${encodeURIComponent(query)}&offset=${offset}&limit=50`);if(generation!==enginesGeneration||query!==$('#engineSearch').value||offset!==state.engOffset)return;if(offset>0&&offset>=r.total){state.engOffset=Math.max(0,Math.floor((r.total-1)/50)*50);return loadEngines()}state.engines=r.items;state.engineTotal=r.total;state.libraryTotal=r.library_total;$('#engineCount').textContent=r.library_total.toLocaleString(ArenaI18n.locale);$('#enginePage').textContent=ArenaI18n.m`${r.total?state.engOffset+1:0}–${Math.min(state.engOffset+50,r.total)} of ${r.total.toLocaleString(ArenaI18n.locale)}`;syncEngineSelection();stableHtml('#engineTable tbody',r.items.map(p=>ArenaI18n.h`<tr><td><input type="checkbox" aria-label="Select ${esc(p.name)}" data-engine="${p.id}" ${state.selected.has(p.id)?'checked':''}></td><td><b>${esc(p.name)}</b><small>${esc(p.identity?.name||ArenaI18n.t('Identity not yet tested'))}</small>${p.move_book?`<small>${ArenaI18n.t('Engine move book')}: ${esc(p.move_book.name)}</small>`:''}</td><td>${profileResource(p,'threads',1)}</td><td>${profileResource(p,'hash',1024)} MB</td><td>${esc(tcText(p.time_control))}</td><td class="path-cell" title="${esc(p.path)}">${esc(p.path)}</td><td><button data-edit="${p.id}" class="subtle">Configure</button><button data-delete-engine="${p.id}" class="danger-quiet" aria-label="Delete ${esc(p.name)}" data-help="Remove this profile from the library. The executable and saved tournament records are kept.">Delete…</button></td></tr>`).join(''));$$('[data-engine]').forEach(e=>e.onchange=()=>{e.checked?state.selected.add(e.dataset.engine):state.selected.delete(e.dataset.engine);syncEngineSelection()});$$('[data-edit]').forEach(e=>e.onclick=()=>editEngine(state.engines.find(p=>p.id===e.dataset.edit)));}
