 modal(profile.id?ArenaI18n.t('Configure engine profile'):ArenaI18n.t('Add UCI engine'),ArenaI18n.h`<div class="fields">${pathField('epath',ArenaI18n.t('Engine executable'),profile.path)}${field('ename',ArenaI18n.t('Profile name'),profile.name)}${field('eargs',ArenaI18n.t('Launch arguments (quoted paths supported)'),Array.isArray(profile.args)?profile.args.map(a=>a.includes(' ')?'"'+a+'"':a).join(' '):profile.args||'')}${pathField('ecwd',ArenaI18n.t('Working directory (blank = executable folder)'),profile.cwd||'',true)}${field('ethreads',ArenaI18n.t('CPU threads'),profile.threads??1,'number','min="1"')}${field('ehash',ArenaI18n.t('Hash memory (MB per engine)'),profile.hash??1024,'number','min="1"')}${field('eaffinity',ArenaI18n.t('CPU affinity (comma-separated logical CPU numbers)'),(profile.affinity||[]).join(','))}${field('egpu',ArenaI18n.t('Shared GPU group (blank = CPU only)'),profile.gpu_group||'')}${field('eextra',ArenaI18n.t('Additional memory per engine (MB)'),profile.extra_memory_mb??256,'number','min="0"')}<div class="field"><label><input id="eindependent" type="checkbox" ${profile.time_control?'checked':''}> Independent time control / handicap</label></div></div><div id="engineTc" ${profile.time_control?'':'hidden'}><div class="section-label">ENGINE TIME CONTROL</div>${tcEditor('etc',profile.time_control)}</div>${engineBookEditor(profile)}<div class="section-label">ADVERTISED UCI OPTIONS</div><p class="caption">Test connection discovers the engine name, version and every advertised option. Threads and Hash stay synchronized with the resource fields above.</p><div class="options">${optionsHtml(profile)}</div>`,ArenaI18n.h`<button id="testEngine">Test connection & discover</button><button class="primary" id="saveEngine">Save profile</button>`);wireBrowsers();wireTc('etc');$('#eindependent').onchange=()=>$('#engineTc').hidden=!$('#eindependent').checked;
