function countGames(n,f,c,p,r,ca){let pairs;if(['match','sprt'].includes(f))pairs=c;else if(f==='self_play')pairs=n*c;else if(f==='round_robin')pairs=n*(n-1)/2*c;else if(f==='gauntlet')pairs=ca*(n-ca)*c;else if(f==='knockout')pairs=(n-1)*c;else if(f==='double_elimination')pairs=(2*n-2)*c;else pairs=Math.floor(n/2)*r*c;return pairs*(p?2:1)}
