let tournamentListGeneration=0,tournamentListCheckedAt=performance.now();
async function refreshTournamentList(){
 const now=performance.now();if(now-tournamentListCheckedAt<5000)return;
 // Reconcile stages created by the event worker or another window, including
 // an empty workspace. Bound retries and avoid replacing unchanged options.
 tournamentListCheckedAt=now;await loadTournaments();
}
// A tournament may be deleted by another window or an API client while selected.
// Reconcile that selection without treating a healthy worker as disconnected.
async function refreshSelectedTournament(){
 const tid=state.tid;
 try{await refreshTournament()}
 catch(error){
  if(state.tid!==tid)return;
  if(error.serverMessage!=='Tournament not found')throw error;
  await loadTournaments();if(state.tid===tid)throw error;
  if($('#error').textContent===ArenaI18n.message(error.message))notify('',true);
  renderBoards();if(state.tid)await refreshTournament();
 }
}
