let refreshing=false,tick=0;
async function refresh(){
 if(refreshing)return;refreshing=true;
 try{
  let s;
  try{s=await api('status')}
  catch(error){
   state.connected=false;if(typeof hardwareDisconnected==='function')hardwareDisconnected();
   $('#sideStatus').textContent=ArenaI18n.t('Worker connection lost — saved results retained');
   notify(ArenaI18n.message(error.message),true);return;
  }
  state.connected=true;
  if(typeof renderQueueSummary==='function')renderQueueSummary(s.tournament_queue);
  state.live=s.live.map(g=>({...g,receivedAt:performance.now()}));
  state.recentFinished=s.recent_finished||[];
  if(typeof renderManagerResources==='function')renderManagerResources(s.scheduling);
  if(typeof recordHardware==='function')recordHardware(s);
  $('#sideStatus').textContent=ArenaI18n.m`${s.active_games} active games · ${s.logical_cpus} logical CPUs`;
  if(typeof renderHardware==='function')renderHardware(s);
  if(typeof renderWorkerHealth==='function')renderWorkerHealth(s);
  if(typeof renderPgnOutputStatus==='function')renderPgnOutputStatus(s.pgn_outputs);
  if(s.error)notify(ArenaI18n.message(s.error),true);
  await refreshTournamentList();
  if(state.tid){renderBoards();if(tick++%2===0)await refreshSelectedTournament()}
 }catch(error){notify(ArenaI18n.message(error.message),true)}
 finally{refreshing=false}
}
safely(async()=>{
 const savedView=state.view;let showingRecovery=false,recovery;
 while((recovery=await api('storage')).maintenance.busy){
  if(!showingRecovery){view('health');$('#pageTitle').textContent=ArenaI18n.t('Worker & recovery');showingRecovery=true}
  await refresh();
  if(typeof refreshStorage==='function')await refreshStorage();
  await new Promise(resolve=>setTimeout(resolve,750));
 }
 await loadEngines();await loadTournaments();
 if(recovery.maintenance.error)notify(recovery.maintenance.error,true);
 else if(showingRecovery){notify(ArenaI18n.t('Storage recovery finished. Saved tournaments are ready.'));if(savedView&&state.view==='health')view(savedView)}
 await refresh();setInterval(refresh,750);
})();

