 const job=await api(`experiments/${id}?offset=${offset}`);if(generation!==experimentResultsGeneration)return;
 modal(job.name,ArenaI18n.h`<div id="experimentResultsPanel" data-id="${id}"><p id="experimentProgress"></p><details><summary>How to read these results</summary><p class="caption">${ArenaI18n.t(experimentNote)}</p></details><div id="experimentSummary"></div><div class="table-scroll" style="max-height:48vh"><table><thead><tr><th>ENGINE / CASE</th><th>THREADS</th><th>MOVE</th>${job.kind==='suite'?ArenaI18n.h`<th>ACCURACY</th>`:''}<th>ELAPSED (s)</th>${job.kind==='suite'?ArenaI18n.h`<th>SOLVE (s)</th>`:''}<th>MEASURED NPS</th><th>STATUS</th></tr></thead><tbody id="experimentRows"></tbody></table></div><div class="toolbar"><button id="experimentPrev">Previous</button><span id="experimentPage"></span><button id="experimentNext">Next</button></div></div>`,ArenaI18n.h`<button id="exportExperiment">Export JSON</button><button id="experimentText">Text…</button><button id="cancelExperiment">Stop current case</button>`);
